SELECT PROVIDER_FNAME ,PROVIDER_MNAME ,PROVIDER_LNAME ,PROVIDER_SUFFIX, NPI ,COUNTY_FIPS ,ADDRESS ,CITY, STATE, ZIPCODE , PLUS4, PHONE , TO_CHAR(HIERARCHY) HIERARCHY, rwnum FROM ( SELECT PROVIDER_FNAME ,PROVIDER_MNAME ,PROVIDER_LNAME ,PROVIDER_SUFFIX, NPI ,COUNTY_FIPS ,ADDRESS ,CITY, STATE, ZIPCODE , PLUS4, PHONE, LAST_UPDATED_DATE , CASE WHEN STATE = 'NY' and county_fips not in ('005', '047', '061', '081', '085') THEN 4 when STATE = 'NY' and county_fips in ('005', '047', '061', '081', '085') THEN 3 when STATE = 'NY' and county_fips is null THEN 2 WHEN STATE != 'NY' THEN 1 ELSE 0 END HIERARCHY , ROW_NUMBER() OVER ( PARTITION BY raw1.NPI ORDER BY CASE WHEN STATE = 'NY' and county_fips is not null THEN 3 when STATE = 'NY' and county_fips is null THEN 2 WHEN STATE != 'NY' THEN 1 ELSE 0 END DESC, raw_provider_address_id DESC) rwnum FROM RAW_PROVIDER_ADDRESS raw1 WHERE FLIPPED_TO_FACILITY_DATE is null and raw1.NPI IN
#{npi}
) i WHERe rwnum=1

